using SharpCompress.Archives;
using SharpCompress.Common;
using SharpCompress.Readers;

public static void ExtractZip(string archivePath, string outputDir)
{
    using var stream = File.OpenRead(archivePath);
    using var reader = ReaderFactory.Open(stream);

    while (reader.MoveToNextEntry())
    {
        if (!reader.Entry.IsDirectory)
        {
            reader.WriteEntryToDirectory(
                outputDir,
                new ExtractionOptions { ExtractFullPath = true, Overwrite = true }
            );
        }
    }
}

public static void CompressToGzip(string sourceFile, string gzipPath)
{
    using var sourceStream = File.OpenRead(sourceFile);
    using var gzipStream = File.Create(gzipPath);

    var writer = WriterFactory.Open(gzipStream, CompressionType.GZip);
    writer.Write(sourceFile, sourceStream);
    writer.Dispose();
}
